<?php endif; ?><?php foreach ($items as $item): ?><article class="card mb-3"><div class="card-body"><h3><?php echo html_escape((string) $item->display_order . '. ' . $item->question_code); ?></h3><p><?php echo nl2br(html_escape($item->question_text)); ?></p><p><strong>Instruksi bukti</strong><br><?php echo nl2br(html_escape($item->evidence_instruction)); ?></p><p><strong>Kebijakan bukti</strong><br><?php echo html_escape($item->evidence_policy); ?></p><label for="realization-<?php echo (int) $item->assignment_item_id; ?>">Realisasi</label><textarea class="form-control" id="realization-<?php echo (int) $item->assignment_item_id; ?>" name="realization[<?php echo (int) $item->assignment_item_id; ?>]" rows="4" <?php echo $editable ? '' : 'readonly'; ?>><?php echo html_escape($item->realization); ?></textarea><?php if ($editable): ?><label for="evidence-url-<?php echo (int) $item->assignment_item_id; ?>">URL bukti</label><input class="form-control" type="url" id="evidence-url-<?php echo (int) $item->assignment_item_id; ?>" name="evidence_url[<?php echo (int) $item->assignment_item_id; ?>]" value="<?php echo html_escape($item->evidence_url); ?>"><?php elseif ($item->evidence_url): ?><p><strong>URL bukti</strong><br><?php echo html_escape($item->evidence_url); ?></p><?php endif; ?><ul><?php foreach ($item->evidence as $evidence): ?><li><a href="<?php echo site_url('auditee/spmi/evidence/' . (int) $evidence->id . '/download'); ?>"><?php echo html_escape($evidence->original_name); ?></a></li><?php endforeach; ?></ul></div></article><?php endforeach; ?>
<?php if ($editable): ?><button type="submit">Simpan draft</button><?php if ($assignment->submission_status === 'returned_for_revision'): ?><button type="submit" formaction="<?php echo site_url('auditee/spmi/assignment/' . (int) $assignment->id . '/resubmit'); ?>">Kirim ulang revisi</button><?php else: ?><button type="submit" formaction="<?php echo site_url('auditee/spmi/assignment/' . (int) $assignment->id . '/submit'); ?>">Submit sekali</button><?php endif; ?><?php echo form_close(); ?><?php endif; ?>
<?php if ($editable): ?><?php foreach ($items as $item): ?><?php foreach ($item->evidence as $evidence): ?><?php echo form_open('auditee/spmi/evidence/' . (int) $evidence->id . '/delete', ['class' => 'd-inline']); ?><input type="hidden" name="version" value="<?php echo html_escape((string) $version); ?>"><button type="submit">Hapus <?php echo html_escape($evidence->original_name); ?></button><?php echo form_close(); ?><?php endforeach; ?><?php echo form_open_multipart('auditee/spmi/item/' . (int) $item->assignment_item_id . '/evidence/upload'); ?><input type="hidden" name="version" value="<?php echo html_escape((string) $version); ?>"><input type="file" name="evidence" accept="application/pdf,image/jpeg,image/png" required><button type="submit">Upload bukti item <?php echo html_escape((string) $item->display_order); ?></button><?php echo form_close(); ?><?php endforeach; ?><?php elseif ($assignment->state === 'closed'): ?><div class="alert alert-info">Riwayat submission closed bersifat hanya-baca.</div><?php else: ?><div class="alert alert-info">Submission sudah dikirim dan bersifat hanya-baca.</div><?php endif; ?>
<h3>Riwayat revisi</h3><?php if (empty($revision_history)): ?><p>Belum ada riwayat revisi.</p><?php else: ?><ol><?php foreach ($revision_history as $event): ?><li><?php echo html_escape($event->created_at); ?> — <?php echo html_escape($event->previous_status . ' → ' . $event->new_status); ?>, versi <?php echo html_escape((string) $event->previous_version . ' → ' . (string) $event->resulting_version); ?> oleh <?php echo html_escape($event->actor_name ?: $event->actor_email); ?><br><?php echo nl2br(html_escape($event->reason)); ?></li><?php endforeach; ?></ol><?php endif; ?></div></div>
